INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品贮存过程中，应与墙壁、地面保持适当距离。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '进行热烘烤或热卤肉岗位的从业人员可以只穿戴好衣、帽上岗，不用戴口罩，除非是个人自愿戴防烟尘或餐饮单位另定的要求（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者必须委托第三方专业机构开展食品安全自查，及时发现并消除食品安全隐患，防止发生食品安全事故。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '中小学、幼儿园一般不得在校内设置小卖部、超市等食品经营场所，确有需要设置的，应当依法取得许可。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校有发生食品安全事故潜在风险的，应当立即停止食品经营活动，并及时向所在地食品安全监督管理部门和教育部门报告。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '市场监督管理部门进行食品抽样检验时购买抽取的样品并支付样品费用，但可以向食品生产经营者收取检验费和其他费用。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '在生产经营场所配置纱帘、纱网、防鼠板、防蝇灯、风幕等装置，防止鼠类昆虫等侵入。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者可以重复使用一次性餐饮具。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者伪造、涂改、倒卖、出租、出借、转让许可的，由县级以上地方市场监督管理部门责令改正，给予警告，并处一万元以上三万元以下罚款。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '所有食品生产企业必须留存生产信息，建立食品安全追溯体系，保证食品可追溯。国家鼓励食品生产企业采用信息化手段实现食品可追溯。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者取得食品经营许可后，可以再擅自变更布局流程', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业主要负责人每月至少听取1次食品安全总监管理工作情况汇报，对当月食品安全日常管理、风险隐患排查治理等情况进行工作总结，对下个月重点工作作出调度安排，形成《每月食品安全调度会议纪要》。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产经营企业不定期对本企业的食品安全状况进行检查评价。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校食堂餐具、饮具和盛放或者接触直接入口食品的容器、工具，使用前洗净即可', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '复检申请人应当向复检机构先行支付复检费用。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '非传统食品安全风险发生的主要原因是食品生产经营者诚信道德缺失、盲目追求经济利益、市场竞争机制相对不健全等因素，由于发生的随机性较大，防控难度大，因此不能通过制定专门的食品防护计划进行预测和预防。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '复检机构出具的复检结论为最终检验结论。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '县级以上地方市场监督管理部门应当自受理申请之日起十五个工作日内作出是否准予行政许可的决定。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '从事接触直接入口食品的人员应当进行健康检查，取得健康证明后方可上岗工作（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '主要设备设施、经营布局、操作流程等发生较大变化，可能影响食品安全的，餐饮服务提供者应当在变化后十个工作日内向原发证的市场监督管理部门报告。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务从业人员洗手消毒可在流动或非流动水下淋湿双手', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产者认为应当召回的食品，应当立即召回。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '被吊销食品经营许可证的食品经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起三年内不得申请食品生产经营许可。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品添加剂的使用原则之一是：在达到预期效果的前提下尽可能增加在食品中的使用量。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食用农产品不包括法律法规禁止食用的野生动物产品及其制品。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '入网餐饮服务提供者不必须具有实体经营门店。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '委托生产食品、食品添加剂的，委托方、受托方应当遵守法律、法规、食品安全标准以及合同的约定，并将委托生产的食品品种、委托期限、委托方对受托方生产行为的监督等情况予以单独记录，留档备查。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '集体用餐配送单位指主要服务于集体用餐单位，根据其订购要求，集中加工、分送食品并提供就餐场所的餐饮服务提供者。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产经营企业自查时，生产经营条件发生变化，不再符合食品安全要求的，食品生产经营企业应当立即采取整改措施。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '鼓励食品生产经营企业符合良好生产规范要求，实施危害分析与关键控制点体系。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '某食品生产企业2020年因食品安全违法被吊销许可证。2023年其法定代表人、直接负责的主管人员和其他直接责任人员可以担任另一家食品安全总监、食品安全员。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '在加工前，学校食堂应当检查待加工的食品及原料，发现有不符合要求情形的，不得加工或者使用。用水应当符合国家规定的生活饮用水卫生标准。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品包括以治疗为目的物品。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品经营者收到监督抽检不合格检验结论后，应当按照国家市场监督管理总局的规定在被抽检经营场所显著位置公示相关不合格产品信息。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者应建立并执行食品从业人员健康管理制度。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '《中华人民共和国食品安全法》规定了生产经营者自查制度等要求，食品生产经营者要主动防范风险，通过定期对食品安全状况进行检查评价，发现不符合食品安全要求的，应当立即采取整改措施；发生食品安全事故潜在风险的，应当立即停止食品生产经营活动，并向所在地食品安全监督管理部门报告。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校应当与供餐单位签订供餐合同（或者协议），明确双方食品安全与营养健康的权利和义务，存档备查。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '引入社会力量承包或者委托经营学校食堂的，应当以招投标等方式公开选择依法取得食品经营许可、能承担食品安全责任、社会信誉良好的餐饮服务单位或者符合条件的餐饮管理单位。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品安全标准公布后，食品生产经营者可以在食品安全标准规定实施日期之前实施并公开提前实施情况。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '供餐过程中，应对食品采取有效防护措施，如使用清洁的托盘等工具，避免造成食品受到污染。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品、食品添加剂、食品相关产品的生产者，应当按照食品安全标准对所生产的食品、食品添加剂、食品相关产品进行检验，检验合格后方可出厂或者销售。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '在学校食堂，需要再次利用的食品，应当按照相关规范采取热藏或者冷藏方式存放，并在确认没有腐败变质的情况下，对需要加热的食品经高温彻底加热后食用。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
