INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业主要负责人是指在本企业生产经营中承担全面领导责任的法定代表人、实际控制人等主要决策人。直接负责的主管人员是指在违法行为中负有直接管理责任的人员，包括食品安全总监等。其他直接责任人员是指具体实施违法行为并起较大作用的人员，既可以是单位的生产经营管理人员，也可以是单位的职工，包括食品安全员等。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
