INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '鼓励企业建立对食品安全总监、食品安全员的激励机制，对工作成效显著的给予表彰和奖励。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产经营企业根据需要建立健全食品安全管理制度。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '预防为主是指各项工作要关口前移，不要等到发生问题再查处、追责，要通过加强日常监管工作，消除隐患，防患未然。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业对于微生物（如细菌、病毒、朊病毒等）的危害防控措施，可以采用清洁消毒、加热灭菌、低温贮存、添加防腐剂、建立不利于微生物生存繁殖的环境等措施，也可以加强源头控制，消除或降低原料带入产生的危害风险。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '因不当逐利、恶性竞争、社会矛盾和恐怖主义等原因影响，对食品进行的人为故意污染或蓄意破坏，属于传统风险。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品添加剂存在感官性状异常、超过保质期等情形的，应当及时清理。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '有发生食品安全事故潜在风险的，在开展食品生产经营同时，向所在地县级人民政府食品安全监督管理部门报告。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '单位从事食品药品违法行为的，除对单位进行处罚外，还要依法追究单位直接负责的主管人员和其他直接责任人员责任。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '生产经营的食品中可以添加按照传统既是食品又是中药材的物质', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '进入专间和存放在专用操作区的食品应为直接入口食品，应避免受到存放在专间和专用操作区的非食品的污染', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校、托幼机构食堂变更经营形式，自营改为承包经营的，以及承包经营企业发生变化的，应在变化后十个工作日内向原发证的市场监督管理部门报告。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业可以通过建立健全食品安全管理制度，落实食品安全责任制，配备相应的食品安全管理人员，明确岗位职责，制定食品安全风险管控清单和防控措施，落实日管控、周排查、月调度工作制度和机制等方式，防控食品安全风险。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品经营企业应当配备食品安全管理人员并经考核合格。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '依据规定，由连锁总部统一采购的，各门店应能提供企业总部留存的食品供货商的资质证明、食品合格证明文件等资料，并出示有接货清单。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '风险监测是指市场监督管理部门对有食品安全标准的风险因素，开展监测、分析、处理的活动。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品安全管理人员监督抽查考核不得公布考核结果。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '有食品安全法规定的违法情形，除依照食品安全法的规定给予处罚外，有故意实施违法行为、违法行为性质恶劣、违法行为造成严重后果情形之一的，对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员处以其上一年度从本单位取得收入的10倍以上罚款。（）', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产经营者要依法履行食品安全第一责任人的义务，深入查找不合格食品产生的原因。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '根据《中华人民共和国食品安全法》规定，为贯彻落实食品安全法，切实加强对食品安全工作的领导，国务院设立食品安全委员会，其职责由全国人大规定。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '连锁餐饮服务企业总部要制定细化措施，依法推动门店主动对消费者进行防止食品浪费提示提醒，在醒目位置张贴或者摆放反食品浪费标识。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品添加剂都是天然物质。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '在不合格食品复检和异议期间，食品生产经营者不得停止履行风险控制、原因排查、问题整改等义务。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '从业人员必须配戴口罩、帽子、洗手、消毒后才能切配水果  （）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '国家粮食和物资储备局负责粮食流通监督检查，负责粮食收购、储存、运输环节粮食质量安全和原粮卫生的监督管理，组织实施全国粮食库存检查工作。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业主要负责人每月至少听取1次食品安全总监管理工作情况汇报，对当月食品安全日常管理、风险隐患排查治理等情况进行工作总结，对下个月重点工作作出调度安排，形成《每月食品安全调度会议纪要》。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '用餐人数300人以上的托幼机构食堂只需要配备食品安全总监。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '从业人员在食品处理区内不可戴戒指、耳环和项链，可以穿工作服进厕所。（）', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '除中央厨房和集体用餐配送单位以外的餐饮服务提供者冷却直接入口易腐食品和分装、分切等操作，应按规定在专间或者专用操作区进行（在封闭的自动设备中操作和饮品的现场调配、冲泡、分装除外）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品感官性状发生变化的应当废弃，不应再加热后供食用', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '制作食用冰、奶茶、果蔬汁的水，应为符合国家标准规定的生活饮用水。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '进货查验应当记录供应商名称、地址、联系方式等内容。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起三年内不得申请食品生产经营许可，或者从事食品生产经营管理工作、担任食品生产经营企业食品安全管理人员', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务连锁企业总部应根据其经营模式，配备专职食品安全总监、专职食品安全员等食品安全管理人员。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校应当根据卫生健康主管部门发布的学生餐营养指南等标准，针对不同年龄段在校学生营养健康需求，因地制宜引导学生科学营养用餐。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '国家对食品、食品添加剂的生产经营实行许可制度，即在我国从事食品（食品添加剂）生产、食品销售、餐饮服务，应当依法取得许可。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业总部统一查验的许可资质证明、产品合格证明文件等信息，门店应能及时查询。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '批发市场开办者需配备食品安全员，可以不配备食品安全总监。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务场所、设施、设备应定期维护，出现问题及时维修或者更换。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '间接负责的主管人员是指在违法行为中负有管理责任的人员，包括食品安全总监等。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '对食品添加剂以及清洁剂、消毒剂、润滑剂等明确标示、分类管理、妥善保存，可以防范加工过程中带来的化学性危害。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '因食品安全犯罪被判处有期徒刑以上刑罚的人员，表现良好还可以担任食品安全总监、食品安全员。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业及其主要负责人无正当理由未采纳食品安全总监、食品安全员依照《企业落实食品安全主体责任监督管理规定》第四条第二款提出的否决建议的，属于故意实施违法行为的情形。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校食堂应当具有与所经营的食品品种、数量、供餐人数相适应的场所并保持环境整洁，与有毒、有害场所以及其他污染源保持规定的距离。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品安全国家标准在发布前，其草案不需要向社会公开。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产经营企业应合规使用清洁剂、消毒剂等化学品，非必要不在生产经营场所使用和存放可能污染食品的化学制剂。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品抽样检验对推动落实食品安全“两个责任”、排查发现食品安全风险、提升食品安全质量水平发挥着重要作用。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '采用冷冻、冷藏、充氮等低温、隔氧贮存方式，或者建立干燥的生产、贮存环境，创造不利于寄生虫生长的环境条件可以实现对寄生虫的控制。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '核查人员应当自接受现场核查任务之日起五个工作日内，完成对经营场所的现场核查。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者取得食品经营许可后，主体业态和经营项目可以根据经营需要自行调整', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业可以按照生产卫生规范（或良好生产规范）以及危害分析与关键控制点体系（HACCP），对生产过程进行食品安全控制，预防危害带来的食品安全风险。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '进入食品处理区的非从业人员，可以不用符合从业人员卫生要求', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '市场监管部门对严重违法失信企业及其食品安全总监和食品安全员实施市场和行业禁入措施。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校食堂制作的食品在烹饪后应当在一天内食用，需要熟制的食品应当烧熟煮透。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '专间和专用操作区使用的食品容器、工具、设备和清洁工具应专用。食品容器、工具使用前应清洗消毒并保持清洁', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '从业人员处理食品前应进行手部的清洁，如戴手套的可以不用洗手（）', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '霉菌毒素是霉菌产生的有毒代谢产物，对人体可产生较大危害。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '制定和实施合规、合理的食品安全管理制度，也是企业承担食品安全主体责任的重要体现。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品原料、半成品、成品应分隔或者分离贮存', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '法人、负责人要给食品安全管理员提供必要的工作条件，以及培训及学习的机会，积极创造条件使食品安全管理员能履行法定职责（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '实行统一配送经营方式的餐饮服务企业，可由企业总部统一查验供货者的产品合格证明文件。企业总部统一查验的许可资质证明、产品合格证明文件等信息，门店应能及时查询。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务企业应当建立基于食品安全风险防控的动态管理机制，结合企业实际，落实自查要求，制定食品安全风险管控清单，建立健全日管控、周排查、月调度工作制度和机制。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '因食品安全犯罪被判处有期徒刑以上刑罚的人员，终身不得担任食品安全总监、食品安全员。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品添加剂都是人工合成的。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '未加碘食盐的标签可以不标注“未加碘”字样。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '企业应当为食品安全总监、食品安全员提供必要的工作条件、教育培训和岗位待遇，充分保障其依法履行职责。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '实行统一配送方式经营的餐饮服务企业，由企业总部统一进行食品进货查验记录的，各门店也应对收货情况进行记录。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '学校食堂、托幼机构食堂不得申请生食类食品制售项目，不得申请冷食类食品中的冷荤类食品制售、冷加工糕点制售等高风险食品制售项目。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '使用食品添加剂的，应在技术上确有必要，并在达到预期效果的前提下尽可能降低使用量', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务企业、中央厨房、集体用餐配送单位、学校（含托幼机构）食堂、养老机构食堂、医疗机构食堂应如实记录采购的食品、食品添加剂的名称、规格、数量、生产日期或者生产批号、保质期、进货日期和供货者名称、地址、联系方式等内容，并保存相关凭证。食品相关产品可以不用记录。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '分派菜肴、整理造型的工具使用前应清洗消毒', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '幼儿园集中用餐的食品安全与营养健康管理，适用《学校食品安全与营养健康管理规定》。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮外卖平台应当以显著方式提示消费者适量点餐。餐饮服务经营者通过餐饮外卖平台提供服务的，应当在平台页面上向消费者提供食品分量、规格或者建议消费人数等信息。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '国家出入境检验检疫部门（海关）对进出口食品安全实施监督管理。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者应当配备专职的食品安全专业技术人员、食品安全管理人员。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '中小学、幼儿园一般不得在校内设置小卖部、超市等食品经营场所，确有需要设置的，应当依法取得许可，可以售卖高盐、高糖及高脂食品。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品经营企业应当配备食品安全管理人员并经考核合格。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '入网餐饮服务提供者在自己的加工操作区内加工食品，可将订单委托其他食品经营者加工制作。（）', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者隐瞒真实情况或者提供虚假材料申请食品经营许可的，由原发证的市场监督管理部门撤销许可，处一万元以上三万元以下罚款。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '其他直接责任人员是指具体实施违法行为并起较大作用的人员，既可以是单位的生产经营管理人员，也可以是单位的职工，包括食品安全员等。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品抽样检验可以由市场监管部门自行抽样，也可以委托承检机构抽样。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '复检机构不得与初检机构为同一机构。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '连锁餐饮服务企业总部应督促中央厨房、配送中心、门店严格执行食品安全管理制度、操作规程等。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品包括按照传统既是食品又是中药材的物品。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '《最高人民法院关于审理食品安全民事纠纷案件适用法律若干问题的解释》规定，经营者经营明知是不符合食品安全标准的食品，但向消费者承诺的赔偿标准高于食品安全法第一百四十八条规定的赔偿标准，消费者主张经营者按照承诺赔偿的，人民法院应当依法予以支持。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '《关于“三新食品”目录及适用的食品安全标准的公告》（2023年？第4号）规定，在公告前和过渡期内按照原标准和要求生产的新食品原料，可销售和使用至保质期结束。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '对因标签、标识或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售；销售时应当向消费者明示补救措施。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '农业农村部负责农产品质量安全监督管理。组织开展农产品质量安全监测、追溯、风险评估。提出技术性贸易措施建议。参与制定农产品质量安全国家标准并会同有关部门组织实施。指导农业检验检测体系建设。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '集体用餐配送单位食品处理区面积与单次最大供餐人数相适应，县级以上市场监督管理部门可依据实际制定食品处理区面积与供餐人数比例。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '冷食类食品指最后一道工艺是在常温或者低温条件下进行的，包括解冻、切配、调制等过程，加工后在常温或者低温条件下即可食用的食品。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '鼓励外卖包装封签，鼓励外卖配送食品在容器或者包装上标注食用时限，并提醒消费者收到后尽快食用。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品加工用水的水质应符合GB5749《生活饮用水卫生标准》规定。对加工用水水质有特殊需要的，应符合相应规定', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '不应重复使用一次性餐（饮）具。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品原料加工前应洗净。未经事先清洁的禽蛋使用前应清洁外壳，必要时消毒。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '网络外卖配送需冷藏食品，也可以常温配送（）', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '连锁食品经营企业应当建立健全覆盖从总部到门店的食品安全管理体系。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '《中华人民共和标准化法》规定，企业执行自行制定的企业标准的，还应当公开产品、服务的功能指标和产品的性能指标。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '连锁餐饮服务企业总部依法要对企业食品安全负总责，建立健全覆盖从总部到门店（包括直营、合营、加盟等）的食品安全管理体系。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品安全员每日根据风险管控清单进行检查，形成《每日食品安全检查记录》，对发现的食品安全风险隐患，应当立即采取防范措施，按照程序及时上报食品安全总监或者企业主要负责人。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '对陪餐家长在学校食品安全与营养健康等方面提出的意见建议收集后不用进行反馈。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '集体用餐配送单位配送的食品，应在包装、容器或者配送箱上标注集体用餐配送单位信息、加工时间和食用时限，冷藏保存的食品还应标注保存条件和食用方法', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '废弃物存放设施应有盖，能够防止污水渗漏、不良气味溢出和虫害孳生，并易于清洁。废弃物存放设施应及时清洁，必要时消毒。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产企业可以制定严于食品安全国家标准或者地方标准的企业标准，但要符合法律、法规和强制性标准的规定，作为企业组织生产经营的依据。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，建立健全食品安全管理制度，采取有效措施预防和控制食品安全风险，保证食品安全。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '真菌毒素超标，易导致食物中毒、致病、致癌与食源性疾病不相关。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务经营者可以不执行《食品安全国家标准 餐饮服务通用卫生规范》中的某些要求', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者地址迁移，不在原许可经营场所从事餐饮服务活动的，应当在十个工作日内向原发证的市场监督管理部门申请变更食品经营许可。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品处理区内从业人员不应留长指甲、但可以涂指甲油。（）', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '国务院食品安全委员会组织开展食品安全风险监测评估，依法制定并公布食品安全标准。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者需要延续依法取得的食品经营许可有效期的，应当在该食品经营许可有效期届满前十五个工作日内，向原发证的市场监督管理部门提出申请。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者可随意使用食品添加剂', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者可以贮存亚硝酸盐', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '非从业人员不得进入食品处理区。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '存在感官性状异常、超过保质期等情形的，应及时清理', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务经营者可以加工经营野生河鲀。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '入网餐饮服务提供者应当在餐饮服务经营活动主页面公示餐饮服务提供者的食品经营许可证。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '逾期未提出复检申请的，不予受理。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者地址迁移，不在原许可经营场所从事食品经营活动的，可以继续使用原来的许可证', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '外卖餐配送前应对配送工具和盛装食品的容器（一次性容器除外）进行清洁，接触直接入口食品的还应消毒，防止食品受到污染。（）', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '食品生产经营者可以拒绝或者阻挠食品安全抽样工作。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者应当建立食品安全信息追溯、消费者投诉处理等方面的食品安全管理制度。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '县级以上地方市场监督管理部门按照国家市场监督管理总局制定的食品安全管理人员考核指南，组织对本辖区餐饮服务单位的食品安全总监、食品安全员随机进行监督抽查考核，无需公布考核结果。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '配送的食品应有包装，或者盛装在密闭容器中。食品包装和容器应符合食品安全相关要求，食品容器的内部结构应便于清洁。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '禁止以药膳名义食用或者生产、经营禁止食用的动物及其制品。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '配送过程中，直接入口食品和非直接入口食品、需低温保存的食品和热食品应分隔，防止直接入 口食品污染，并保证食品温度符合食品安全要求。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '国家卫生健康委员会印发的《按照传统既是食品又是中药材的物质目录管理规定》明确了食药物质的动态调整和管理规范。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '餐饮服务提供者建立餐饮具清洗消毒管理制度，规范清洗、消毒、保洁流程。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '餐饮', '易', '是', NULL, '排水管道出水口安装的篦子应使用金属材料制成，篦子缝隙间距或网眼应小于8mm。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
